#pragma once
// Palette entries for the gameplay camera nodes. NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after pin()/attr()
// are defined, and calls appendCameraNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphCameraNodeTable.cs pin for pin (docs/CAMERAS.md, Aver Node family "Camera").
// Entities are ints; enums cross as ints: mode 0 Chase, 1 Orbit, 2 FirstPerson, 3 Seat, 4 TopDown, 5 Fixed; preset 0 Chase,
// 1 VehicleChase, 2 Orbit, 3 FirstPerson, 4 Seat, 5 TopDown, 6 Fixed; curve 0 EaseInOut, 1 Linear, 2 EaseIn, 3 EaseOut.
// Events CameraViewTargetChanged, CameraBlendFinished and CameraCut reach a graph through AN_OnEvent.

inline void appendCameraNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"AN_CameraAddRig", "Add Camera Rig", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("preset", "int", false, "0"), pin("target", "int", false, "0"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraSetMode", "Set Camera Mode", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("mode", "int", false, "0"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraSetTarget", "Set Camera Target", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("target", "int", false),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraSetViewTarget", "Set View Target", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("blendSeconds", "float", false, "0.5"), pin("curve", "int", false, "0"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraClearViewTarget", "Clear View Target", "Camera", {
        pin("exec", "exec", false), pin("blendSeconds", "float", false, "0.5"), pin("curve", "int", false, "0"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraCut", "Camera Cut", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false, "0"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraSetArm", "Set Camera Arm", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("lengthCm", "float", false, "450"), pin("probeRadiusCm", "float", false, "12"),
        pin("collide", "bool", false, "true"), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraSetSocket", "Set Camera Socket", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraSetPivot", "Set Camera Pivot", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraSetLag", "Set Camera Lag", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("posSpeed", "float", false, "10"), pin("rotSpeed", "float", false, "0"),
        pin("maxDistCm", "float", false, "0"), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraSetLookAhead", "Set Camera Look Ahead", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("seconds", "float", false, "0.25"), pin("maxCm", "float", false, "150"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraSetLimits", "Set Camera Pitch Limits", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("pitchMinDeg", "float", false, "-80"), pin("pitchMaxDeg", "float", false, "80"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraAddLook", "Add Camera Look", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("yawDeg", "float", false), pin("pitchDeg", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraSetFade", "Set Camera Fade", "Camera", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("startCm", "float", false, "140"), pin("endCm", "float", false, "70"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraPushFovKick", "Camera FOV Kick", "Camera", {
        pin("exec", "exec", false), pin("deltaDeg", "float", false, "8"), pin("inSeconds", "float", false, "0.05"),
        pin("holdSeconds", "float", false, "0.1"), pin("outSeconds", "float", false, "0.4"),
        pin("then", "exec", true), pin("id", "int", true)}});
    t.push_back({"AN_CameraPushZoom", "Camera Zoom", "Camera", {
        pin("exec", "exec", false), pin("fovScale", "float", false, "0.6"), pin("blendSeconds", "float", false, "0.2"),
        pin("then", "exec", true), pin("id", "int", true)}});
    t.push_back({"AN_CameraPunch", "Camera Punch", "Camera", {
        pin("exec", "exec", false), pin("pitchDeg", "float", false), pin("yawDeg", "float", false), pin("rollDeg", "float", false),
        pin("recoverSeconds", "float", false, "0.3"), pin("then", "exec", true), pin("id", "int", true)}});
    t.push_back({"AN_CameraRemoveModifier", "Remove Camera Modifier", "Camera", {
        pin("exec", "exec", false), pin("id", "int", false), pin("outSeconds", "float", false, "-1"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraClearModifiers", "Clear Camera Modifiers", "Camera", {
        pin("exec", "exec", false), pin("tag", "int", false, "0"), pin("then", "exec", true), pin("count", "int", true)}});
    t.push_back({"AN_CameraShakeAt", "Camera Shake At", "Camera", {
        pin("exec", "exec", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("radiusCm", "float", false, "1500"), pin("intensity", "float", false, "0.6"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_CameraGetPose", "Get Camera Pose", "Camera", {
        pin("x", "float", true), pin("y", "float", true), pin("z", "float", true), pin("yawDeg", "float", true), pin("pitchDeg", "float", true),
        pin("rollDeg", "float", true), pin("fovDeg", "float", true), pin("found", "bool", true)}});
    t.push_back({"AN_CameraGetRigState", "Get Camera Rig State", "Camera", {
        pin("entity", "int", false), pin("armCm", "float", true), pin("colliding", "bool", true), pin("active", "bool", true),
        pin("blending", "bool", true), pin("found", "bool", true)}});
    t.push_back({"AN_CameraGetViewTarget", "Get View Target", "Camera", {
        pin("entity", "int", true), pin("blending", "bool", true), pin("blendAlpha", "float", true)}});
}
